#!/usr/bin/env node
// One entrypoint for propagating Markdown source edits into all source-linked
// metadata. The published Pagefind index is regenerated by npm run build.
import { spawnSync } from "node:child_process";

const [mode, ...flags] = process.argv.slice(2);
if (!["--check", "--sync"].includes(mode) ||
    flags.some(flag => !/^--approve-fragments=\d+(?:,\d+)*$/.test(flag)) ||
    flags.length > 1 || (mode === "--check" && flags.length)) {
  console.error("Usage: npm run source:check | npm run source:sync [-- --approve-fragments=138,421]");
  process.exit(2);
}
const approvePages = flags[0]?.split("=")[1];
const commands = mode === "--check"
  ? [
      ["Bibi spelling", ["run", "content:bibi:check"]],
      ["Basta index", ["run", "basta:index:check"]],
      ["Reviewed fragment boundaries", ["run", "basta:fragments:check"]],
      ["Recitation IDs", ["run", "recitation:ids:check"]],
      ["Fragment classification and editorial regression", ["run", "content:review", "--", "--summary", "--regression"]],
    ]
  : [
      ["Canonical Bibi spelling", ["run", "content:bibi:fix"]],
      ["Basta index titles", ["run", "basta:index:sync"]],
      ["Review approved fragment openings", ["run", "basta:fragments:" + (approvePages ? "approve" : "check"),
        ...(approvePages ? ["--", "--pages=" + approvePages] : [])]],
      ["Stable recitation fingerprints", ["run", "recitation:ids:sync"]],
      ["Full source verification", ["run", "source:check"]],
    ];

for (const [label, args] of commands) {
  console.log("\n=== Source " + (mode === "--sync" ? "sync" : "check") + ": " + label + " ===");
  const result = spawnSync("npm", args, { stdio: "inherit", shell: false });
  if (result.error || result.status !== 0) {
    console.error("\nSource update stopped at " + label + ".");
    if (mode === "--sync") console.error(
      "No further metadata was refreshed. Review changed Markdown/manifest entries; " +
      "published IDs must never be reassigned automatically.");
    process.exit(result.status || 1);
  }
}
console.log("\nSource " + (mode === "--sync" ? "synchronization" : "validation") +
  " passed. The production build regenerates rendered pages, Pagefind, and the offline search manifest.");
